// a one-slot channel acts as the guard: free = idle, full = running
var slot = make(chan struct{}, 1)

func TryStart() bool {
	select {
	case slot <- struct{}{}: // acquired the right to run, right now
		return true
	default: // someone else is running: balk
		return false
	}
}
func Finish() { <-slot }

