// Machine has: mu sync.Mutex, state State
func (m *Machine) TryStart() bool {
	if !m.mu.TryLock() { // contention: balk
		return false
	}
	defer m.mu.Unlock()
	if m.state != Idle { // state forbids the action
		return false
	}
	m.state = Running
	return true
}
